`timescale 1ns/1ps
// Die-name calendar sequencers (Q-DVM+LINK 2026-10-15; r2 2026-10-16): one per link end, the compiler images as
// constants (d2d_cal_image.svh, generated by tools/qwen_split/d2d_cal_seq_image.py).  They produce the link end's cfg_* /
// cal_start / cal_seg inputs.  Both run the ADMISSION segment once per epoch at D2D_ADM_OFS edges after the forwarded
// epoch strobe (epoch_go).  Compute: the token start is tok_go from qfd_sys_face's token loop (first token
// D2D_FIRST_TOKEN after the strobe, then every D2D_TOKEN_PERIOD).  KV: AUTO token starts by the same rule, counted from
// its own fwd_epoch output EP_SKEW edges earlier (EP_SKEW = the package bump latency to the compute fwd_epoch pin), so
// both dies' token runs start on the same edge with no per-token handshake.  See ot_qwen_d2d_cal_seq.sv.
`include "d2d_cal_image.svh"
module qfd_d2d_cal_seq #(parameter integer GO_OFS = 0, parameter [20*36-1:0] START_ADJ = '0) (
    input wire ck, rst_n, reload, tok_go, epoch_go, halt,
    output wire cfg_tx_we, cfg_rx_we, output wire [5:0] cfg_addr, output wire [31:0] cfg_data,
    output wire cal_start, cal_seg, cal_ready, running, output wire [5:0] layer, output wire adm_done, tok_start, fault);
    ot_qwen_d2d_cal_seq #(.GO_OFS(GO_OFS), .TX_IMG(D2D_CAL_C_TX_IMG), .RX_IMG(D2D_CAL_C_RX_IMG),
        .TX_SEG1(D2D_CAL_C_TX_SEG1), .RX_SEG1(D2D_CAL_C_RX_SEG1), .START(D2D_CAL_START + START_ADJ),
        .ADM(1), .TX_SEG2(D2D_CAL_C_TX_SEG2), .RX_SEG2(D2D_CAL_C_RX_SEG2), .ADM_OFS(D2D_ADM_OFS), .ADM_LEN(D2D_ADM_LEN),
        .AUTO(0), .FIRST_OFS(D2D_FIRST_TOKEN), .PERIOD(D2D_TOKEN_PERIOD), .EP_SKEW(0)) u_seq (
        .ck(ck), .rst_n(rst_n), .reload(reload), .tok_go(tok_go), .epoch_go(epoch_go), .halt(halt), .cfg_tx_we(cfg_tx_we),
        .cfg_rx_we(cfg_rx_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data), .cal_start(cal_start), .cal_seg(cal_seg),
        .cal_ready(cal_ready), .running(running), .layer(layer), .adm_done(adm_done), .tok_start(tok_start), .fault(fault));
endmodule
// KV end: tok_go is unused (AUTO); EP_SKEW = package bump edges from the KV fwd_epoch output to the compute pin
module qkd_d2d_cal_seq #(parameter integer GO_OFS = 0, parameter [20*36-1:0] START_ADJ = '0, parameter integer EP_SKEW = 3) (
    input wire ck, rst_n, reload, tok_go, epoch_go, halt,
    output wire cfg_tx_we, cfg_rx_we, output wire [5:0] cfg_addr, output wire [31:0] cfg_data,
    output wire cal_start, cal_seg, cal_ready, running, output wire [5:0] layer, output wire adm_done, tok_start, fault);
    ot_qwen_d2d_cal_seq #(.GO_OFS(GO_OFS), .TX_IMG(D2D_CAL_K_TX_IMG), .RX_IMG(D2D_CAL_K_RX_IMG),
        .TX_SEG1(D2D_CAL_K_TX_SEG1), .RX_SEG1(D2D_CAL_K_RX_SEG1), .START(D2D_CAL_START + START_ADJ),
        .ADM(1), .TX_SEG2(D2D_CAL_K_TX_SEG2), .RX_SEG2(D2D_CAL_K_RX_SEG2), .ADM_OFS(D2D_ADM_OFS), .ADM_LEN(D2D_ADM_LEN),
        .AUTO(1), .FIRST_OFS(D2D_FIRST_TOKEN), .PERIOD(D2D_TOKEN_PERIOD), .EP_SKEW(EP_SKEW)) u_seq (
        .ck(ck), .rst_n(rst_n), .reload(reload), .tok_go(tok_go), .epoch_go(epoch_go), .halt(halt), .cfg_tx_we(cfg_tx_we),
        .cfg_rx_we(cfg_rx_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data), .cal_start(cal_start), .cal_seg(cal_seg),
        .cal_ready(cal_ready), .running(running), .layer(layer), .adm_done(adm_done), .tok_start(tok_start), .fault(fault));
endmodule
